-- Conceptual PostgreSQL schema. The runnable demo uses SQLAlchemy + SQLite.
CREATE TABLE users (id SERIAL PRIMARY KEY, name VARCHAR(120) NOT NULL, email VARCHAR(180) UNIQUE NOT NULL, password_hash VARCHAR(255) NOT NULL, role VARCHAR(30) NOT NULL, language VARCHAR(12) DEFAULT 'en');
CREATE TABLE farms (id SERIAL PRIMARY KEY, owner_id INTEGER NOT NULL REFERENCES users(id), name VARCHAR(120) NOT NULL, crop VARCHAR(80) NOT NULL, variety VARCHAR(80), stage VARCHAR(80), region VARCHAR(120), area_acres NUMERIC(8,2), latitude NUMERIC(9,6), longitude NUMERIC(9,6));
CREATE TABLE disease_cases (id SERIAL PRIMARY KEY, farm_id INTEGER NOT NULL REFERENCES farms(id), farmer_id INTEGER NOT NULL REFERENCES users(id), crop VARCHAR(80) NOT NULL, diagnosis VARCHAR(120) NOT NULL, confidence NUMERIC(5,2), risk VARCHAR(20), status VARCHAR(40), symptoms TEXT, image_path VARCHAR(255), region VARCHAR(120), created_at TIMESTAMP WITH TIME ZONE DEFAULT now());
CREATE TABLE sensor_data (id SERIAL PRIMARY KEY, farm_id INTEGER NOT NULL REFERENCES farms(id), temperature NUMERIC(5,2), humidity NUMERIC(5,2), soil_moisture NUMERIC(5,2), leaf_wetness NUMERIC(5,2), trap_count INTEGER, created_at TIMESTAMP WITH TIME ZONE DEFAULT now());
CREATE TABLE expert_reviews (id SERIAL PRIMARY KEY, case_id INTEGER NOT NULL REFERENCES disease_cases(id), reviewer_id INTEGER NOT NULL REFERENCES users(id), decision VARCHAR(30), diagnosis VARCHAR(120), comments TEXT, created_at TIMESTAMP WITH TIME ZONE DEFAULT now());
